            "value": {
                "value": "${$vars.start.output.webhookPayload.customer.accountNumber}",
                "rawString": "\"${$vars.start.output.webhookPayload.customer.accountNumber}\"",
                "isLiteral": False
            }
        }
    ],
    "groups": []
}

erp_filter_tree = {
    "groupOperator": 0,
    "index": 0,
    "filters": [
        {
            "id": "invoiceNumber",
            "operator": "Equals",
            "value": {
                "value": "${$vars.normalizeData1.output.invoiceNumber}",
                "rawString": "\"${$vars.normalizeData1.output.invoiceNumber}\"",
                "isLiteral": False
            }
        }
    ],
    "groups": []
}

crm_ceql = "accountNumber = '${$vars.start.output.webhookPayload.customer.accountNumber}'"
erp_ceql = "invoiceNumber = '${$vars.normalizeData1.output.invoiceNumber}'"

for node in flow['nodes']:
    if node['id'] == 'crmLookup1':
        detail = node['inputs']['detail']
        # 1. Runtime: inject queryParameters.queryExpression
        if 'queryParameters' not in detail:
            detail['queryParameters'] = {}
        detail['queryParameters']['queryExpression'] = crm_ceql
        # 2. Design-time: inject savedFilterTrees into the =jsonString: blob
        cfg_str = detail['configuration']
        assert cfg_str.startswith('=jsonString:')
        inner = json.loads(cfg_str[len('=jsonString:'):])
        inner['essentialConfiguration']['savedFilterTrees'] = {
            'queryExpression': crm_filter_tree
        }
        detail['configuration'] = '=jsonString:' + json.dumps(inner, separators=(',', ':'))
        print('crmLookup1 updated')

    elif node['id'] == 'erpLookup1':
        detail = node['inputs']['detail']
        # 1. Runtime: inject queryParameters.queryExpression
        if 'queryParameters' not in detail:
            detail['queryParameters'] = {}
        detail['queryParameters']['queryExpression'] = erp_ceql
        # 2. Design-time: inject savedFilterTrees into the =jsonString: blob
        cfg_str = detail['configuration']
        assert cfg_str.startswith('=jsonString:')
        inner = json.loads(cfg_str[len('=jsonString:'):])
        inner['essentialConfiguration']['savedFilterTrees'] = {
            'queryExpression': erp_filter_tree
        }
        detail['configuration'] = '=jsonString:' + json.dumps(inner, separators=(',', ':'))
        print('erpLookup1 updated')

with open('BillingDisputeResolution.flow', 'w') as f:
    json.dump(flow, f, indent=2)

print('Flow file written successfully')
